// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/access/Ownable.sol";

/// @title EncryptedStorageSerializer
/// @notice Serializes structured data for off-chain NoSQL storage with on-chain verification
contract EncryptedStorageSerializer is Ownable {

    struct StorageRecord {
        bytes32 collectionId;
        bytes encryptedPayload;
        uint256 timestamp;
        address author;
    }

    struct QueryFilter {
        string fieldPath;
        string operator;
        bytes value;
    }

    mapping(bytes32 => StorageRecord[]) private collections;
    mapping(address => bool) public authorizedWriters;
    mapping(bytes32 => bytes32) private encryptionKeys;

    event RecordStored(bytes32 indexed collectionId, uint256 index, address author);
    event QueryExecuted(bytes32 indexed collectionId, address executor);

    modifier onlyAuthorized() {
        require(authorizedWriters[msg.sender] || msg.sender == owner(), "Unauthorized");
        _;
    }

    constructor() Ownable(msg.sender) {
        authorizedWriters[msg.sender] = true;
    }

    function authorizeWriter(address writer) external onlyOwner {
        authorizedWriters[writer] = true;
    }

    function setEncryptionKey(bytes32 collectionId, bytes32 key) external onlyOwner {
        encryptionKeys[collectionId] = key;
    }

    /// @notice Serializes and stores an encrypted record
    function storeRecord(
        bytes32 collectionId,
        bytes calldata payload,
        bytes32 nonce
    ) external onlyAuthorized returns (uint256) {
        require(encryptionKeys[collectionId] != bytes32(0), "Collection not initialized");

        bytes memory encrypted = _encryptPayload(payload, collectionId, nonce);

        StorageRecord memory record = StorageRecord({
            collectionId: collectionId,
            encryptedPayload: encrypted,
            timestamp: block.timestamp,
            author: msg.sender
        });

        collections[collectionId].push(record);
        uint256 index = collections[collectionId].length - 1;

        emit RecordStored(collectionId, index, msg.sender);
        return index;
    }

    /// @notice Builds a serialized query filter for off-chain NoSQL execution
    /// @dev The serialized output is consumed by the off-chain indexer
    function buildQueryFilter(
        bytes32 collectionId,
        QueryFilter[] calldata filters
    ) external onlyAuthorized returns (bytes memory) {
        require(filters.length > 0 && filters.length <= 10, "Invalid filter count");

        bytes memory serialized = _serializeQueryHeader(collectionId);

        for (uint256 i = 0; i < filters.length; i++) {
            serialized = _appendFilterCondition(
                serialized,
                filters[i]
            );
        }

        emit QueryExecuted(collectionId, msg.sender);
        return serialized;
    }

    /// @notice Internal serialization of query header
    function _serializeQueryHeader(bytes32 collectionId) internal pure returns (bytes memory) {
        return abi.encodePacked(
            '{"collection":"',
            _bytes32ToHexString(collectionId),
            '","filters":['
        );
    }

    /// @notice Appends a filter condition to the serialized query
    /// @dev Validates operator, field path, and value to prevent injection
    function _appendFilterCondition(
        bytes memory current,
        QueryFilter calldata filter
    ) internal pure returns (bytes memory) {
        require(_isValidOperator(filter.operator), "Invalid operator");
        // Field path validation: allow nested paths with dots, alphanumeric only
        require(bytes(filter.fieldPath).length > 0, "Empty field path");
        require(bytes(filter.fieldPath).length <= 128, "Field path too long");
        require(_isValidFieldPath(filter.fieldPath), "Invalid field path characters");
        // Value validation: must be a safe JSON primitive (no objects/operators)
        require(_isValidJsonValue(filter.value), "Invalid value format");

        bytes memory condition = abi.encodePacked(
            '{"field":"',
            filter.fieldPath,
            '","op":"',
            filter.operator,
            '","value":',
            filter.value,
            '}'
        );

        return abi.encodePacked(current, condition);
    }

    /// @notice Validates that field path contains only safe characters
    function _isValidFieldPath(string calldata path) internal pure returns (bool) {
        bytes memory b = bytes(path);
        for (uint256 i = 0; i < b.length; i++) {
            bytes1 c = b[i];
            // Allow alphanumeric, dots for nesting, underscores
            bool isAlpha = (c >= 0x41 && c <= 0x5A) || (c >= 0x61 && c <= 0x7A);
            bool isDigit = (c >= 0x30 && c <= 0x39);
            bool isDot = (c == 0x2E);
            bool isUnderscore = (c == 0x5F);
            if (!(isAlpha || isDigit || isDot || isUnderscore)) {
                return false;
            }
        }
        return true;
    }

    /// @notice Validates that value is a safe JSON primitive (string, number, bool, null)
    /// @dev Rejects any value containing $ (MongoDB operator prefix) or { (object start)
    function _isValidJsonValue(bytes calldata value) internal pure returns (bool) {
        if (value.length == 0 || value.length > 256) return false;
        for (uint256 i = 0; i < value.length; i++) {
            // Reject MongoDB operator injection characters
            if (value[i] == 0x24) return false; // $
            if (value[i] == 0x7B) return false; // {
        }
        return true;
    }

    /// @notice Validates query operators against allowlist
    function _isValidOperator(string calldata op) internal pure returns (bool) {
        bytes32 opHash = keccak256(bytes(op));
        return (
            opHash == keccak256("$eq") ||
            opHash == keccak256("$gt") ||
            opHash == keccak256("$lt") ||
            opHash == keccak256("$gte") ||
            opHash == keccak256("$lte") ||
            opHash == keccak256("$in") ||
            opHash == keccak256("$ne")
        );
    }

    /// @notice XOR-based encryption with collection key using counter-mode keystream
    /// @dev Keystream is derived per 32-byte block via keccak256(derivedKey, blockIndex)
    ///      to avoid keystream repetition on payloads longer than 32 bytes.
    function _encryptPayload(
        bytes calldata payload,
        bytes32 collectionId,
        bytes32 nonce
    ) internal view returns (bytes memory) {
        bytes32 key = encryptionKeys[collectionId];
        bytes32 derivedKey = keccak256(abi.encodePacked(key, nonce));

        bytes memory result = new bytes(payload.length);
        bytes32 keystreamBlock;
        for (uint256 i = 0; i < payload.length; i++) {
            if (i % 32 == 0) {
                // Generate a fresh keystream block for each 32-byte chunk (CTR-style)
                keystreamBlock = keccak256(abi.encodePacked(derivedKey, i / 32));
            }
            result[i] = payload[i] ^ bytes1(keystreamBlock[i % 32]);
        }
        return abi.encodePacked(nonce, result);
    }

    function _bytes32ToHexString(bytes32 data) internal pure returns (string memory) {
        bytes memory alphabet = "0123456789abcdef";
        bytes memory str = new bytes(64);
        for (uint256 i = 0; i < 32; i++) {
            str[i*2] = alphabet[uint8(data[i]) >> 4];
            str[i*2+1] = alphabet[uint8(data[i]) & 0x0f];
        }
        return string(str);
    }

    function getRecordCount(bytes32 collectionId) external view returns (uint256) {
        return collections[collectionId].length;
    }
}
